<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS decaissements (id INT AUTO_INCREMENT PRIMARY KEY,feb_id INT NOT NULL,montant DECIMAL(15,2) NOT NULL,date_decaissement DATE NOT NULL,reference_paiement VARCHAR(150),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_cash_out_feb(feb_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
